{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver tredje betingelse forkert. Det siger, at man \"næsten ikke kan have et studiejob\", mens kilderne kræver varig funktionsnedsættelse med meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde. Svaret nævner heller ikke, at tillægget gives sammen med SU-stipendium eller slutlån. Det tilføjer desuden udsagn om lavere fribeløb og minSU, som ikke har støtte i materialet."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element er kun delvist med: svaret nævner ret til SU, men ikke slutlån og ikke, at tillægget udbetales sammen med SU-stipendium eller slutlån. Svaret siger \"videregående uddannelse eller erhvervsuddannelse\", men ikke \"dansk\" EUD. Det tredje element er omformuleret til \"næsten ikke kan have et studiejob\" i stedet for \"meget betydelige begrænsninger i evnen til erhvervsarbejde\". Det er en ændring af tærsklen og ikke blot en ækvivalent formulering."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er rettet mod spørgsmålet om betingelser og opregner betingelser for SU-handicaptillæg. Det indeholder også noget tillægsstof, men det erstatter ikke svaret."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser ikke til nogen identificerbar lovbestemmelse, vejledningsafsnit eller bekendtgørelse. Det nævner kun generelt SU.dk og minSU, hvilket ikke er en konkret kilde til de juridiske udsagn."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret angiver ingen identificerbar kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen angivne kilder, så det kan ikke vurderes, om de understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at man \"næsten ikke kan have et studiejob\", at et lavere fribeløb gælder, og at ansøgning sker via minSU. Intet af dette støttes i det udleverede materiale. Udsagnet om, at SU kan bede om flere oplysninger, har nogenlunde støtte i § 37, stk. 5, men resten er ikke understøttet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke kravet om \"meget betydelige begrænsninger i evnen til erhvervsarbejde\" og udelader, at EUD skal være dansk. Det angiver heller ikke, at tillægget gives sammen med SU-stipendium eller slutlån."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: betingelserne opregnes, og det forklares, at en diagnose alene ikke er afgørende, men at den konkrete påvirkning vurderes. Konklusionen følger af de trin, der er angivet."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Formuleringen \"næsten ikke kan have et studiejob\" skærper tærsklen og afviger fra kildens \"meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde\". Udsagnet om, at man \"skal vedlægge\" dokumentation, passer nogenlunde med § 37, stk. 1. Den ændrede tærskel gør dog, at modaliteten ikke er gengivet præcist."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "partial",
      "reason": "Svaret kræver, at man har ret til SU, men gengiver ikke udtrykkeligt de almindelige betingelser for SU eller slutlån, og slutlån nævnes ikke."
    },
    "A2": {
      "label": "partial",
      "reason": "Svaret nævner indskrivning på en SU-berettiget videregående uddannelse eller erhvervsuddannelse, men ikke at EUD skal være dansk. Det omtaler heller ikke EUX eller udelukkelsen af udenlandske erhvervslignende uddannelser."
    },
    "A3": {
      "label": "partial",
      "reason": "Svaret nævner varig fysisk eller psykisk funktionsnedsættelse, men erstatter \"meget betydelige begrænsninger i evnen til erhvervsarbejde\" med \"næsten ikke kan have et studiejob\"."
    },
    "A4": {
      "label": "yes",
      "reason": "Svaret kræver indskrivning på en SU-berettiget uddannelse og ret til SU, hvilket svarer til punktet."
    },
    "A6": {
      "label": "no",
      "reason": "Svaret angiver ikke, at dansk EUD, herunder EUX, er omfattet, og nævner ikke udelukkelsen af erhvervslignende uddannelser uden for Danmark."
    }
  },
  "overall_notes": "Svaret rammer tre grundtanker, men omformulerer den centrale tærskel for funktionsnedsættelsens betydning for erhvervsevnen. Det udelader, at tillægget gives sammen med SU-stipendium eller slutlån, og at EUD skal være dansk. Det tilføjer desuden udsagn om fribeløb og minSU uden støtte i materialet og angiver ingen konkret kilde."
}

